// Version-pinned process-local adapter; upstream DRY is called unchanged.
// No weights or task-specific code are generated by this controller.
#include "llama-sampler-abi.h"
#include "phase.h"
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <dlfcn.h>
#include <fcntl.h>
#include <fstream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <sys/stat.h>
#include <unistd.h>
#include <vector>

namespace {
constexpr const char * VERSION="rtl-author-control-v3";
constexpr const char * ABI="f114f91";
template<class T>T symbol(const char * name) {
    auto p=reinterpret_cast<T>(dlsym(RTLD_NEXT,name));
    if(!p){std::fprintf(stderr,"author control: missing public symbol %s\n",name);std::abort();}
    return p;
}
using Factory=llama_sampler *(*)(const llama_vocab *,float,float,int32_t,int32_t,const char **,size_t);
using Init=llama_sampler *(*)(llama_sampler_i *,void *);
using Accept=void(*)(llama_sampler *,llama_token);
using Apply=void(*)(llama_sampler *,llama_token_data_array *);
using Reset=void(*)(llama_sampler *);
using Free=void(*)(llama_sampler *);
using Clone=llama_sampler *(*)(const llama_sampler *);
using Copy=void(*)(const llama_sampler *,llama_sampler *);
using Piece=int32_t(*)(const llama_vocab *,llama_token,char *,int32_t,int32_t,bool);
using Tokenize=int32_t(*)(const llama_vocab *,const char *,int32_t,llama_token *,int32_t,bool,bool);
const std::string directory(){const char * s=std::getenv("RTL_AUTHOR_CONTROL_DIR");return s?s:"";}
bool safe_directory(const std::string & s) {
    struct stat st{};
    return !s.empty()&&s[0]=='/'&&s!="/"&&lstat(s.c_str(),&st)==0&&S_ISDIR(st.st_mode)&&
        st.st_uid==getuid()&&(st.st_mode&0022)==0;
}
void append(const std::string & path,const std::string & row) {
    int fd=open(path.c_str(),O_CREAT|O_APPEND|O_WRONLY|O_NOFOLLOW,0600);
    if(fd<0){std::fprintf(stderr,"author control: audit unavailable\n");std::abort();}
    const auto text=row+'\n';size_t n=0;
    while(n<text.size()){const auto w=write(fd,text.data()+n,text.size()-n);if(w<=0){close(fd);std::abort();}n+=size_t(w);}
    close(fd);
}
struct Control {
    const llama_vocab * vocab;
    llama_sampler * dry;
    std::string id,path,format;
    rtl_control::Tracker tracker;
    int soft=4096,late=8192,reserve=10240;
    bool dry_enabled=true,converge=true,pending=false,injected=false;
    uint64_t tokens=0,analysis_tokens=0,code_tokens=0,unknown_tokens=0,apply_calls=0,dry_steps=0,changed_steps=0,changed_candidates=0,forced_count=0;
    std::vector<llama_token> forced;size_t force_pos=0;
    std::vector<float> originals;
    std::vector<int8_t> protection;
    std::string piece(llama_token token) const {
        static const auto f=symbol<Piece>("llama_token_to_piece");
        char b[256];int n=f(vocab,token,b,sizeof(b),0,true);
        if(n>=0)return std::string(b,n);
        if(n < -65536)return "<unknown>";
        std::string s(-n,'\0');n=f(vocab,token,s.data(),s.size(),0,true);
        return n>=0?s.substr(0,n):"<unknown>";
    }
    void event(const char * type,const char * reason="none") const {
        const auto ms=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
        std::ostringstream s;
        s<<"{\"version\":\""<<VERSION<<"\",\"abi\":\""<<ABI<<"\",\"request_id\":\""<<id<<"\",\"event\":\""<<type
         <<"\",\"reason\":\""<<reason<<"\",\"at_ms\":"<<ms<<",\"phase\":\""<<rtl_control::name(tracker.phase)
         <<"\",\"dry_enabled\":"<<(dry_enabled&&tracker.phase==rtl_control::Phase::analysis&&!injection_active()?"true":"false")
         <<",\"tokens\":"<<tokens<<",\"analysis_tokens\":"<<analysis_tokens<<",\"code_tokens\":"<<code_tokens
         <<",\"unknown_tokens\":"<<unknown_tokens<<",\"apply_calls\":"<<apply_calls<<",\"dry_steps\":"<<dry_steps
         <<",\"changed_steps\":"<<changed_steps<<",\"changed_candidates\":"<<changed_candidates<<",\"injected_tokens\":"<<forced_count<<"}";
        append(path,s.str());
    }
    bool injection_active()const{return force_pos<forced.size();}
    void begin_injection(const char * reason) {
        std::string cue="\nI will implement the established plan now, without another self-test, alternative design, or rewrite. I will submit one complete artifact.\n";
        if(tracker.thinking)cue+="</think>\n";
        if(format=="rtl")cue+="<answer>\n```systemverilog\n";
        static const auto f=symbol<Tokenize>("llama_tokenize");
        int n=f(vocab,cue.data(),cue.size(),nullptr,0,false,true);
        if(n>=0||n < -1024){event("injection_rejected","tokenization");injected=true;return;}
        forced.resize(-n);n=f(vocab,cue.data(),cue.size(),forced.data(),forced.size(),false,true);
        if(n<0){forced.clear();event("injection_rejected","tokenization");injected=true;return;}
        forced.resize(n);injected=true;force_pos=0;
        symbol<Reset>("llama_sampler_reset")(dry);event("convergence_injected",reason);
    }
};
const char * name(const llama_sampler *){return "rtl-author-control-v3";}
void accept(llama_sampler * s,llama_token t) {
    auto & c=*static_cast<Control *>(s->ctx);
    if(!c.pending)return; // prompt ingestion is not generated analysis/history
    c.pending=false;const auto before=c.tracker.phase;const bool forced=c.injection_active();
    if(forced){if(t!=c.forced[c.force_pos]){c.event("fatal","forced_token_mismatch");std::abort();}++c.force_pos;++c.forced_count;}
    ++c.tokens;
    if(before==rtl_control::Phase::analysis)++c.analysis_tokens;
    else if(before==rtl_control::Phase::code||before==rtl_control::Phase::draft)++c.code_tokens;
    else ++c.unknown_tokens;
    const auto p=c.piece(t);c.tracker.push(p);
    if(before!=c.tracker.phase||forced||c.tracker.phase!=rtl_control::Phase::analysis)
        symbol<Reset>("llama_sampler_reset")(c.dry);
    else if(c.dry_enabled)symbol<Accept>("llama_sampler_accept")(c.dry,t);
    if(before!=c.tracker.phase)c.event("phase_change");
    if(forced&&!c.injection_active())c.event("convergence_finished");
    if(c.tokens%256==0)c.event("progress");
}
void apply(llama_sampler * s,llama_token_data_array * cur) {
    auto & c=*static_cast<Control *>(s->ctx);c.pending=true;++c.apply_calls;
    if(c.converge&&!c.injected&&c.tracker.safe_prose_boundary()) {
        if(c.tokens>=uint64_t(c.soft)&&c.tracker.repetitive())c.begin_injection("repeated_prose");
        else if(c.tokens>=uint64_t(c.late)||c.tokens>=uint64_t(c.reserve))c.begin_injection("code_reserve");
    }
    if(c.converge&&!c.injected&&c.format=="rtl"&&
        (c.tokens>=uint64_t(c.late)||c.tokens>=uint64_t(c.reserve))&&c.tracker.safe_submission_restart()) {
        c.event("draft_abandoned","late_unsubmitted_draft");
        c.tracker.abandon_unsubmitted_draft();
        c.begin_injection("late_unsubmitted_draft");
    }
    if(c.injection_active()) {
        bool found=false;const auto target=c.forced[c.force_pos];
        for(size_t i=0;i<cur->size;++i){const bool keep=cur->data[i].id==target;found|=keep;cur->data[i].logit=keep?0.0f:-std::numeric_limits<float>::infinity();}
        if(!found){c.event("fatal","forced_token_not_in_candidates");std::abort();}
        cur->sorted=false;return;
    }
    if(!c.dry_enabled||c.tracker.phase!=rtl_control::Phase::analysis)return;
    ++c.dry_steps;c.originals.resize(cur->size);
    for(size_t i=0;i<cur->size;++i)c.originals[i]=cur->data[i].logit;
    symbol<Apply>("llama_sampler_apply")(c.dry,cur);
    uint64_t changed=0;
    for(size_t i=0;i<cur->size;++i) {
        if(c.originals[i]==cur->data[i].logit)continue;
        const auto token=cur->data[i].id;
        if(token<0){cur->data[i].logit=c.originals[i];continue;}
        if(c.protection.size()<=size_t(token))c.protection.resize(token+1,-1);
        if(c.protection[token]<0)c.protection[token]=rtl_control::protected_piece(c.piece(token))?1:0;
        if(c.protection[token])cur->data[i].logit=c.originals[i];else ++changed;
    }
    if(changed){++c.changed_steps;c.changed_candidates+=changed;}
}
void reset(llama_sampler * s) {
    auto & c=*static_cast<Control *>(s->ctx);
    symbol<Reset>("llama_sampler_reset")(c.dry);
    // Normal server prompt setup resets before any decode. Never erase evidence.
    if(c.tokens){c.event("fatal","unexpected_live_reset");std::abort();}
    c.pending=false;c.tracker=rtl_control::Tracker{};
}
void free_sampler(llama_sampler * s) {
    auto * c=static_cast<Control *>(s->ctx);c->event("finished");symbol<Free>("llama_sampler_free")(c->dry);delete c;
}
llama_sampler * clone_sampler(const llama_sampler *);
void copy_sampler(const llama_sampler *,llama_sampler *);
llama_sampler_i iface={name,accept,apply,reset,clone_sampler,free_sampler,nullptr,nullptr,nullptr,nullptr,nullptr,copy_sampler};
llama_sampler * clone_sampler(const llama_sampler * s) {
    const auto & old=*static_cast<const Control *>(s->ctx);
    auto * c=new Control(old);c->dry=symbol<Clone>("llama_sampler_clone")(old.dry);
    c->event("cloned","not_supported_in_screening");
    return symbol<Init>("llama_sampler_init")(&iface,c);
}
void copy_sampler(const llama_sampler * s,llama_sampler * d) {
    auto & dst=*static_cast<Control *>(d->ctx);const auto & src=*static_cast<const Control *>(s->ctx);
    auto * inner=dst.dry;symbol<Copy>("llama_sampler_copy")(src.dry,inner);dst=src;dst.dry=inner;
}
__attribute__((constructor)) void loaded() {
    const auto dir=directory();if(!safe_directory(dir))return;
    // LD_PRELOAD is inherited by short-lived helper executables. They must not
    // replace the live inference process receipt with their own soon-dead PID.
    // Only a process actually linked to the required llama ABI can advertise it.
    if(!dlsym(RTLD_NEXT,"llama_sampler_init_dry")||!dlsym(RTLD_NEXT,"llama_token_to_piece"))return;
    append(dir+"/capabilities.jsonl",std::string("{\"version\":\"")+VERSION+"\",\"abi\":\""+ABI+"\",\"pid\":"+std::to_string(getpid())+",\"loaded\":true,\"phase_dry\":true,\"convergence\":true}");
}
}
extern "C" llama_sampler * llama_sampler_init_dry(const llama_vocab * vocab,float multiplier,float base,int32_t allowed,int32_t last,const char ** breakers,size_t n) {
    static const auto original=symbol<Factory>("llama_sampler_init_dry");
    std::string marker;std::vector<const char *> clean;
    for(size_t i=0;i<n;++i) {
        if(std::strncmp(breakers[i],"__RTL_AUTHOR_V1__:",18)==0)marker=breakers[i];else clean.push_back(breakers[i]);
    }
    if(marker.empty())return original(vocab,multiplier,base,allowed,last,breakers,n);
    // Marker fields cannot contain paths or free-form model text.
    static const std::regex pattern(R"(^__RTL_AUTHOR_V1__:([a-f0-9]{32}):(rtl|json):([0-9]+):([0-9]+):([0-9]+):([01]):([01])$)");
    std::smatch m;const auto dir=directory();
    if(!safe_directory(dir)||!std::regex_match(marker,m,pattern)){std::fprintf(stderr,"author control: invalid activation\n");std::abort();}
    auto * c=new Control{};c->vocab=vocab;c->id=m[1];c->format=m[2];c->path=dir+'/'+c->id+".jsonl";
    c->soft=std::stoi(m[3]);c->late=std::stoi(m[4]);c->reserve=std::stoi(m[5]);c->dry_enabled=m[6]=="1";c->converge=m[7]=="1";
    if(c->soft<1||c->late<c->soft||c->late>32768||c->reserve<1||c->reserve>32768||!std::isfinite(multiplier)||multiplier<0||multiplier>0.6f||!std::isfinite(base)||base<1||base>2||allowed<6||allowed>64||last<1||last>1024){std::abort();}
    c->dry=original(vocab,multiplier,base,allowed,last,clean.data(),clean.size());
    c->event("initialized");return symbol<Init>("llama_sampler_init")(&iface,c);
}
